<?php defined('BASEPATH') or exit('No direct script access allowed'); ?>
<label for="<?= $esc($form_id); ?>-name">Nome</label><input id="<?= $esc($form_id); ?>-name" class="form-control" name="task[name]" maxlength="191" value="<?= $esc($values['name']); ?>" required>
<label for="<?= $esc($form_id); ?>-description">Descrição</label><textarea id="<?= $esc($form_id); ?>-description" class="form-control" name="task[description]" maxlength="4000"><?= $esc($values['description']); ?></textarea>
<label for="<?= $esc($form_id); ?>-assignee">Responsável autorizado para tarefas</label><select id="<?= $esc($form_id); ?>-assignee" class="form-control" name="task[assignee_id]" required><option value="">Selecione</option><?php foreach($staff_options as $person){ ?><option value="<?= (int)$person['staffid']; ?>" <?= (int)$values['assignee_id']===(int)$person['staffid']?'selected':''; ?>><?= $esc(trim($person['firstname'].' '.$person['lastname'])); ?></option><?php } ?></select>
<label for="<?= $esc($form_id); ?>-due"><?= !empty($standalone_mode)?'Prazo da tarefa':'Prazo dentro do projeto'; ?></label><input id="<?= $esc($form_id); ?>-due" type="date" class="form-control" name="task[due_date]" value="<?= $esc($values['due_date']); ?>" required>
<?php foreach($values['checklist'] as $i=>$item){ ?><label for="<?= $esc($form_id.'-check-'.$i); ?>"><?= $esc($item['text']); ?></label><input type="hidden" name="task[checklist][<?= $i; ?>][text]" value="<?= $esc($item['text']); ?>"><select id="<?= $esc($form_id.'-check-'.$i); ?>" name="task[checklist][<?= $i; ?>][done]" class="form-control"><option value="0" <?= !$item['done']?'selected':''; ?>>Pendente</option><option value="1" <?= $item['done']?'selected':''; ?>>Concluído</option></select><?php } ?>
<label for="<?= $esc($form_id); ?>-lines">Adicionar itens ao checklist (um por linha, até30 no total)</label><textarea id="<?= $esc($form_id); ?>-lines" name="checklist_lines" class="form-control" maxlength="6000"></textarea>
